const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const center = ee.Geometry.Point([86.428836, 35.879797]);
  const buffer = center.buffer(50000); // 50 km radius
  const date = '2024-08-11';
  const startDate = ee.Date(date).advance(-5, 'day');
  const endDate = ee.Date(date).advance(5, 'day');

  // 2. Data Acquisition - Using Sentinel-2 for water detection
  let s2 = ee.ImageCollection('COPERNICUS/S2_HARMONIZED')
    .filterBounds(buffer)
    .filterDate(startDate, endDate)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30));

  let s2Size = s2.size().getInfo();
  console.log(`Sentinel-2 images (Aug 6-16, 2024): ${s2Size}`);

  // 3. Check for empty collection
  if (s2Size === 0) {
    // Try Landsat 9 as fallback
    let l9 = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')
      .filterBounds(buffer)
      .filterDate(startDate, endDate);

    let l9Size = l9.size().getInfo();
    console.log(`Landsat 9 images (Aug 6-16, 2024): ${l9Size}`);

    if (l9Size === 0) {
      console.log("No images available");
      console.log("<answer>C1</answer>");
      return;
    }
    // Use Landsat 9
    var image = l9.first();
    var waterBand = 'SR_B3'; // Green band for NDWI
    var nirBand = 'SR_B5';
  } else {
    // Use Sentinel-2
    var image = s2.first();
    var waterBand = 'B3'; // Green band for NDWI
    var nirBand = 'B8';
  }

  // 4. Calculate NDWI for water detection
  var ndwi = image.normalizedDifference([waterBand, nirBand]);

  // Apply threshold for water (NDWI > 0 typically indicates water)
  var waterMask = ndwi.gt(0.1); // Conservative threshold for lakes

  // 5. Count water pixels and connected components (lakes)
  var waterCount = waterMask.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: buffer,
    scale: 1000,
    maxPixels: 1e9
  }).get('nd').getInfo();

  console.log(`Water pixels count: ${waterCount}`);

  // 6. Check for no valid pixels
  if (waterCount === null || waterCount === 0) {
    console.log("No water pixels detected");
    console.log("<answer>C2</answer>");
    return;
  }

  // 7. Use connected components to identify distinct lakes
  var components = waterMask.connectedComponents({
    neighborhood: ee.Kernel.square(2),
    maxSize: 1024
  });

  // Count distinct components (lakes) with minimum size
  var lakeCount = components.select('labels')
    .reduceRegion({
      reducer: ee.Reducer.countDistinct(),
      geometry: buffer,
      scale: 1000,
      maxPixels: 1e9
    }).get('labels').getInfo();

  console.log(`Distinct lakes detected: ${lakeCount}`);

  // 8. Validate result
  if (lakeCount === null || lakeCount === undefined) {
    console.log("Calculation failed");
    console.log("<answer>C3</answer>");
  } else if (lakeCount > 3) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
